draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.moveTo(W/2-50, 0);
  ctx.lineTo(W/2-50, H);
  ctx.moveTo(W/2+50, 0);
  ctx.lineTo(W/2+50, H);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2, H/2, 40, 0, 2*Math.PI);
  ctx.fillStyle = 'black';
  ctx.fill();
  ctx.fillStyle = '#cccccc';
  ctx.beginPath();
  ctx.rect(W/2-40, H/2-40+Math.sin(t)*20, 80, 40-Math.abs(Math.sin(t)*20));
  ctx.fill();
  ctx.restore();
}
